const BRAND_RULES = [
  ['claude', /claude|anthropic|sonnet|opus|haiku/],
  ['dalle', /dall-?e|gpt-image/], ['sora', /\bsora/],
  ['openai', /\bgpt|chatgpt|openai|codex|whisper|\btts-|text-embedding|davinci|(^|[^a-z0-9])o[1-9](-|$|\s)/],
  ['gemma', /gemma/], ['gemini', /gemini|bard/], ['google', /google|palm|imagen|veo-?\d/],
  ['qwen', /qwen|qwq|qvq|tongyi|alibaba|dashscope/],
  ['deepseek', /deepseek/],
  ['grok', /grok|\bxai\b|x-ai/],
  ['mistral', /mistral|mixtral|codestral|pixtral|ministral|magistral|devstral/],
  ['meta', /llama|\bmeta\b|meta-/],
  ['kimi', /kimi|moonshot/],
  ['zhipu', /\bglm|zhipu|chatglm|bigmodel/],
  ['minimax', /minimax|abab/],
  ['cohere', /cohere|command-?[ar]|\baya\b/],
  ['perplexity', /perplexity|\bsonar/],
  ['wenxin', /ernie|wenxin|baidu/], ['doubao', /doubao|seed-?\d|bytedance/], ['hunyuan', /hunyuan|tencent/],
  ['stepfun', /stepfun|\bstep-\d/], ['microsoft', /\bphi-?\d|microsoft|azure/], ['nvidia', /nvidia|nemotron/],
  ['flux', /flux|black-forest|\bbfl\b/], ['midjourney', /midjourney/], ['stability', /stable-?diffusion|sdxl|\bsd3|stability/],
  ['ideogram', /ideogram/], ['recraft', /recraft/], ['suno', /suno/], ['kling', /kling/], ['runway', /runway|\bgen-?[34]/],
  ['ai21', /jamba|ai21/], ['jina', /jina/], ['voyage', /voyage/], ['baichuan', /baichuan/], ['internlm', /internlm|intern-?vl/],
  ['baai', /\bbge-|baai/], ['spark', /spark|iflytek/], ['yi', /\byi-|01-ai|lingyi/],
];
const PRESET_BRAND = { openai: 'openai', anthropic: 'claude', google: 'gemini', deepseek: 'deepseek', xai: 'grok', mistral: 'mistral', groq: 'groq', openrouter: 'openrouter', together: 'together' };
function brandOf(...parts) {
  const s = parts.filter(Boolean).join(' ').toLowerCase();
  for (const [k, re] of BRAND_RULES) if (re.test(s)) return k;
  return null;
}
// Square tile with the brand mark; falls back to initials when nothing matches.
function brandTile(key, label, sm) {
  const svg = key && BRAND_SVG[key];
  if (!svg) return `<div class="plogo ${sm ? 'sm' : ''}" title="${esc(label || '')}">${esc((label || '?').replace(/[^A-Za-zА-Яа-я0-9]/g, '').slice(0, 2).toUpperCase())}</div>`;
  return `<div class="plogo pb ${sm ? 'sm' : ''}" title="${esc(label || '')}">${svg}</div>`;
}
const modelLogo = (m, sm) => brandTile(brandOf(m.id, m.name, m.family), m.id, sm);
